fn reverse(a: Vec<char>) -> Vec<char> {
    // `into_iter()` takes ownership of `a`,
    // `rev()` reverses the iterator,
    // and `collect()` gathers it back into a Vec<char>.
    a.into_iter().rev().collect()
}

fn main() {
    let input: Vec<char> = vec!['h', 'e', 'l', 'l', 'o'];
    let output = reverse(input.clone());
    assert_eq!(output, vec!['o', 'l', 'l', 'e', 'h']);

    let input2: Vec<char> = vec!['A'];
    let output2 = reverse(input2.clone());
    assert_eq!(output2, vec!['A']);

    println!("All tests passed!");
}